export const getSearchEmployeeDirectoryUrl = (params: SearchEmployeeDirectoryParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `http://localhost:5080/admin/admins/directory?${stringifiedParams}` : `http://localhost:5080/admin/admins/directory`
}

export const searchEmployeeDirectory = async (params: SearchEmployeeDirectoryParams, options?: RequestInit): Promise<searchEmployeeDirectoryResponse> => {
  
  const res = await fetch(getSearchEmployeeDirectoryUrl(params),
  {      
    ...options,
    method: 'GET'
    
    
  }
)

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();
  
  const data: searchEmployeeDirectoryResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as searchEmployeeDirectoryResponse
}



